154	std::unique_ptr<IDataType::SubstreamData> IDataType::getSubcolumnData(
155	    std::string_view subcolumn_name,
156	    const SubstreamData & data,
157	    size_t initial_array_level,
158	    bool throw_if_null)
159	{
160	    std::unique_ptr<IDataType::SubstreamData> res;
161	
162	    ISerialization::StreamCallback callback_with_data = [&](const auto & subpath)
163	    {
164	        for (size_t i = 0; i < subpath.size(); ++i)
165	        {
166	            size_t prefix_len = i + 1;
167	            if (!subpath[i].visited && ISerialization::hasSubcolumnForPath(subpath, prefix_len))
168	            {
169	                auto name = ISerialization::getSubcolumnNameForStream(subpath, prefix_len, false, initial_array_level);
170	                /// Create data from path only if it's requested subcolumn.
171	                /// Use the first match to be consistent with ColumnsDescription::addSubcolumns
172	                /// which also keeps the first subcolumn when there are name collisions
173	                /// (e.g. "null" can match both Nullable's null-map and a Tuple element named "null").
174	                if (name == subcolumn_name && !res)
175	                {
176	                    res = std::make_unique<SubstreamData>(ISerialization::createFromPath(subpath, prefix_len));
177	                }
178	                /// Check if this subcolumn is a prefix of requested subcolumn and it can create dynamic subcolumns.
179	                else if (subcolumn_name.starts_with(name + ".") && subpath[i].data.type && subpath[i].data.type->hasDynamicSubcolumnsData())
180	                {
181	                    auto dynamic_subcolumn_name = subcolumn_name.substr(name.size() + 1);
182	                    auto dynamic_subcolumn_data = subpath[i].data.type->getDynamicSubcolumnData(
183	                        dynamic_subcolumn_name,
184	                        subpath[i].data,
185	                        initial_array_level + ISerialization::getArrayLevel(subpath, prefix_len),
186	                        false);
187	                    if (dynamic_subcolumn_data)
188	                    {
189	                        /// Create requested subcolumn using dynamic subcolumn data.
190	                        auto tmp_subpath = subpath;
191	                        if (tmp_subpath[i].creator)
192	                        {
193	                            dynamic_subcolumn_data->type = tmp_subpath[i].creator->create(dynamic_subcolumn_data->type);
194	                            dynamic_subcolumn_data->column = tmp_subpath[i].creator->create(dynamic_subcolumn_data->column);
195	                            dynamic_subcolumn_data->serialization = tmp_subpath[i].creator->create(dynamic_subcolumn_data->serialization, dynamic_subcolumn_data->type);
196	                        }
197	
198	                        tmp_subpath[i].data = *dynamic_subcolumn_data;
199	                        res = std::make_unique<SubstreamData>(ISerialization::createFromPath(tmp_subpath, prefix_len));
200	                    }
201	                }
202	            }
203	            subpath[i].visited = true;
204	        }
205	    };
206	
207	    ISerialization::EnumerateStreamsSettings settings;
208	    settings.position_independent_encoding = false;
209	    /// Don't enumerate dynamic subcolumns, they are handled separately.
210	    settings.enumerate_dynamic_streams = false;
211	    settings.enumerate_virtual_streams = true;
212	    settings.array_level = initial_array_level;
213	    data.serialization->enumerateStreams(settings, callback_with_data, data);
214	
215	    if (!res && data.type->hasDynamicSubcolumnsData())
216	        return data.type->getDynamicSubcolumnData(subcolumn_name, data, settings.array_level, throw_if_null);
217	
218	    if (!res && throw_if_null)
219	        throw Exception(ErrorCodes::ILLEGAL_COLUMN, "There is no subcolumn {} in type {}", subcolumn_name, data.type->getName());
220	
221	    return res;
222	}
