240	bool IDataType::hasDynamicSubcolumns() const
241	{
242	    if (hasDynamicSubcolumnsData())
243	        return true;
244	
245	    bool has_dynamic_subcolumns = false;
246	    auto data = SubstreamData(getDefaultSerialization()).withType(getPtr());
247	    auto callback = [&](const SubstreamPath &, const String &, const SubstreamData & subcolumn_data)
248	    {
249	        has_dynamic_subcolumns |= subcolumn_data.type && subcolumn_data.type->hasDynamicSubcolumnsData();
250	    };
251	    forEachSubcolumn(callback, data);
252	    return has_dynamic_subcolumns;
253	}

